import {lessons,modules,transactions} from './content.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n/100);
const key='application-academy:v1';
let storageOK=true;let runTimer;
function read(){try{return JSON.parse(localStorage.getItem(key))||{}}catch{storageOK=false;return {}}}
let saved=read(); let progress=saved.progress||{},drafts=saved.drafts||{};
let current=Math.max(0,Math.min(9,Number(location.hash.slice(1))||0)),category='All',plain=false,step=0,hint=false,solution=false,revealed=false,tab='preview',feedback='',selected=-1,network='success',busy=false,runId=0,runnerSource;
function persist(){try{localStorage.setItem(key,JSON.stringify({progress,drafts}))}catch{storageOK=false}}
function navigate(i){current=i;location.hash=i;hint=false;solution=false;revealed=false;feedback='';selected=-1;tab='preview';render()}
function complete(){progress[current]=revealed?'guided':'independent';persist()}
function finance(){const rows=transactions.filter(t=>category==='All'||t.category===category);return `<div class="finance ${plain?'plain':''}"><div class="preview-heading"><span class="mini-logo">£</span><div><strong>Pocket ledger</strong><small>Fictional practice data · GBP</small></div><span class="badge">DEMO</span></div><div class="summary"><small>Net flow · visible records</small><strong>${money(rows.reduce((s,t)=>s+t.amountPence,0))}</strong><span>${rows.length} transaction${rows.length===1?'':'s'}</span></div><label class="filter">Category <select id="category">${['All','Food','Travel','Income'].map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select></label><div class="records">${rows.map(t=>`<div class="record"><span class="record-icon">${t.category==='Income'?'↙':'↗'}</span><span><strong>${esc(t.payee)}</strong><small>${t.category}</small></span><b class="${t.amountPence>0?'positive':''}">${money(t.amountPence)}</b></div>`).join('')}</div></div>`}
function visual(l){if(l.visual==='trace')return `<div class="trace"><div class="eyebrow">ILLUSTRATED SAVE · NO SERVER CONNECTED</div>${['Browser collects category change','API receives an HTTP request','Python validates and authorises','PostgreSQL stores the change','Response confirms the save','Browser displays success'].map((s,i)=>`<div class="trace-row ${i===step?'active':''}"><span>${i+1}</span>${s}</div>`).join('')}<button id="step">${step===5?'Start again':'Next step →'}</button></div>`;
if(l.visual==='storage')return `<div class="storage-demo"><span class="big-icon">▤</span><h3>A small persistence experiment</h3><p>Save a note, then reload this page. Your note stays in this browser.</p><label>Practice note<textarea id="note" placeholder="What did you learn about persistence?">${esc(saved.note||'')}</textarea></label><button id="save-note">Save note locally</button><p id="note-status" role="status"></p></div>`;
if(l.visual==='network')return `<div class="network-demo"><div class="eyebrow">SIMULATED RESPONSE STATES</div><div class="segmented">${['loading','success','empty','error'].map(s=>`<button data-network="${s}" class="${network===s?'chosen':''}">${s}</button>`).join('')}</div>${network==='success'?finance():`<div class="empty-state"><span class="big-icon">${network==='error'?'!':network==='loading'?'◌':'○'}</span><h3>${network==='error'?'Could not load transactions':network==='loading'?'Loading transactions…':'No transactions found'}</h3><p>${network==='error'?'The request failed. Your records may still exist.':network==='loading'?'Wait for a response before drawing conclusions.':'The request succeeded and returned an empty list.'}</p>${network==='error'?'<button id="retry">Try again (simulation)</button>':''}</div>`}</div>`;
return `${l.visual==='style'?'<button class="subtle" id="style-toggle">Toggle plain presentation</button>':''}${finance()}${l.visual==='state'?`<div class="state-strip"><span><b>Data</b>4 records</span><span><b>State</b>${category}</span><span><b>Derived</b>Filtered rows + subtotal</span></div>`:''}`;}
function workspace(l){if(l.visual==='code')return `<div class="workspace-top"><span class="file-label">exercise.js</span><span class="badge">REAL JAVASCRIPT</span></div><label class="sr-only" for="code">JavaScript exercise</label><textarea id="code" spellcheck="false">${esc(drafts[current]??l.starter)}</textarea><div class="editor-actions"><button id="run" ${busy?'disabled':''}>${busy?'Running…':'▶ Run & check'}</button><button class="subtle" id="reset-code">Reset code</button><small>Ctrl / ⌘ + Enter</small></div><div class="output" role="status">${feedback||'<span class="muted">Your output will appear here.</span>'}</div><p class="sandbox-note">Runs in a disposable worker inside an isolated frame. Execution stops after 2 seconds.</p>`;
return visual(l)}
function render(){const l=lessons[current],count=Object.keys(progress).length;$('#app').innerHTML=`<aside><a class="brand" href="#0"><span class="brand-symbol">a<span>·</span></span><span>Application<br><b>Academy</b></span></a><div class="course-label">YOUR LEARNING PATH</div><div class="course-name">Understand what you build.</div><div class="progress-meta"><span>${count} of 10 lessons practised</span><b>${Math.round(count/10*100)}%</b></div><div class="progress-track"><i style="width:${count*10}%"></i></div><nav>${modules.map((m,i)=>`<div class="module-label ${i>1?'future':''}"><span>${String(i+1).padStart(2,'0')}</span>${m}${i>1?'<small>SOON</small>':''}</div>${i<2?lessons.map((lesson,j)=>((i===0&&j<6)||(i===1&&j>=6))?`<button class="lesson-link ${j===current?'active':''}" data-lesson="${j}"><span class="lesson-marker">${progress[j]?'✓':'○'}</span>${lesson.title}</button>`:'').join(''):''}`).join('')}</nav><div class="sidebar-footer"><span class="live-dot"></span> First draft · 10 hands-on lessons<button id="reset-progress">Reset learning progress</button></div></aside><main><header><span>THE FOUNDATIONS <span class="slash">/</span> ${current<6?'HOW APPLICATIONS WORK':'JAVASCRIPT FOR DATA'}</span><span class="header-right">Learn by understanding <span class="avatar">DC</span></span></header><div class="page-content"><div class="lesson-meta"><span class="pill">${esc(l.tag)}</span><span>◷ ${l.time} min</span><span>Lesson ${current+1} of 10</span></div><h1>${l.title}</h1><p class="lead">${l.question}</p><div class="learning-layout"><section class="lesson-panel"><div class="section-kicker"><span>01</span> UNDERSTAND</div><p>${l.body}</p><div class="why"><strong>Why this matters</strong><p>${l.why}</p></div><div class="section-kicker"><span>02</span> EXPERIMENT</div><p>${l.experiment}</p><div class="task-box"><div class="section-kicker"><span>03</span> YOUR TURN</div><p>${l.task}</p>${l.choices?`<fieldset><legend class="sr-only">Choose an answer</legend>${l.choices.map((c,i)=>`<label class="answer ${selected===i?'selected':''}"><input type="radio" name="answer" value="${i}" ${selected===i?'checked':''}><span>${esc(c)}</span></label>`).join('')}</fieldset><button id="check-answer">Check my understanding →</button>`:''}<div class="help-actions"><button id="hint" class="text-button">${hint?'Hide hint':'Get a hint'}</button><button id="solution" class="text-button">${solution?'Hide answer':'Reveal answer'}</button></div>${hint?`<div class="hint">${l.hint}</div>`:''}${solution?`<div class="hint"><strong>Reference answer</strong>${l.solution?`<pre>${esc(l.solution)}</pre>`:`<p>${esc(l.choices[l.answer])}</p>`}<p>${l.explain}</p><small>Run or check the answer to record guided practice.</small></div>`:''}${l.choices?`<div class="feedback" role="status">${feedback}</div>`:''}</div>${progress[current]?`<div class="completion">✓ ${progress[current]==='guided'?'Guided practice complete':'Independent check passed'}</div>`:''}</section><section class="practice-panel"><div class="practice-title"><div><span class="live-dot"></span> THE PRACTICE LAB</div><span>Safe to experiment</span></div><div class="tabs" role="group" aria-label="Workspace view">${['preview','input','trace'].map(t=>`<button class="${tab===t?'active':''}" data-tab="${t}">${t==='preview'?(l.visual==='code'?'Code & output':'Live preview'):t==='input'?'Input data':'How it works'}</button>`).join('')}</div><div class="practice-body">${tab==='preview'?workspace(l):tab==='input'?`<div class="eyebrow">FICTIONAL INPUT · INTEGER PENCE</div><pre class="input-data">${esc(JSON.stringify(transactions,null,2))}</pre>`:`<div class="explanation-flow"><div>User changes a control or runs code</div><span>↓</span><div>JavaScript reads inputs and computes a result</div><span>↓</span><div>The interface shows the result</div></div><p class="muted">This academy runs locally in your browser. The finance preview has no connected API or database. Your practice progress is saved separately in browser storage.</p>`}</div><div class="lab-footer">◇ Fictional data. Real concepts. Room to make mistakes.</div></section></div><footer class="lesson-footer"><button class="subtle" id="previous" ${current===0?'disabled':''}>← Previous lesson</button><span>${storageOK?'Progress saved in this browser':'Browser storage unavailable · progress may not persist'}</span><button id="next">${current===9?'Back to the beginning ↗':'Next lesson →'}</button></footer></div></main>`;bind()}
function bind(){document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>navigate(+b.dataset.lesson));$('.brand').onclick=e=>{e.preventDefault();navigate(0)};$('#previous').onclick=()=>navigate(current-1);$('#next').onclick=()=>navigate((current+1)%10);$('#hint').onclick=()=>{hint=!hint;render()};$('#solution').onclick=()=>{solution=!solution;revealed=true;render()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#category')?.addEventListener('change',e=>{category=e.target.value;render()});$('#style-toggle')?.addEventListener('click',()=>{plain=!plain;render()});$('#step')?.addEventListener('click',()=>{step=(step+1)%6;render()});document.querySelectorAll('[data-network]').forEach(b=>b.onclick=()=>{network=b.dataset.network;render()});$('#retry')?.addEventListener('click',()=>{network='success';render()});$('#save-note')?.addEventListener('click',()=>{saved.note=$('#note').value;try{localStorage.setItem('application-academy:note',saved.note);$('#note-status').textContent='Saved. Reload the page to try it.'}catch{$('#note-status').textContent='Storage unavailable. Your note could not be saved.'}});document.querySelectorAll('input[name="answer"]').forEach(r=>r.onchange=()=>{selected=+r.value});$('#check-answer')?.addEventListener('click',()=>{if(selected===lessons[current].answer){complete();feedback=`<strong class="positive">Correct.</strong> ${lessons[current].explain}`}else feedback=selected<0?'Choose an answer first.':'Not quite. Try the experiment again, or open a hint.';render()});$('#code')?.addEventListener('input',e=>{drafts[current]=e.target.value;persist()});$('#code')?.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run()}});$('#run')?.addEventListener('click',run);$('#reset-code')?.addEventListener('click',()=>{delete drafts[current];feedback='';persist();render()});$('#reset-progress').onclick=()=>{if(confirm('Reset course completion? Your code drafts and practice note will stay.')){progress={};persist();render()}}}
async function run(){if(busy)return;busy=true;feedback='Running your code…';const lessonIndex=current,id=++runId;render();try{runnerSource??=await fetch('checks.js').then(r=>{if(!r.ok)throw Error('Could not load checker');return r.text()});const source=runnerSource.replace('export function evaluate','function evaluate')+'\nself.onmessage=({data})=>{try{self.postMessage(evaluate(data.code,data.kind,data.transactions))}catch(e){self.postMessage({error:e.message})}}';const frame=$('#execution-frame');frame.contentWindow.postMessage({type:'run',id,source,payload:{code:drafts[current]??lessons[current].starter,kind:lessons[current].check,transactions}},'*');window.pendingLesson=lessonIndex;runTimer=setTimeout(()=>{if(busy&&runId===id){busy=false;feedback='The isolated runner did not respond. Reload the page and try again.';render()}},5000)}catch(e){busy=false;feedback=esc(e.message);render()}}
addEventListener('message',e=>{if(e.source!==$('#execution-frame')?.contentWindow||e.data?.type!=='result'||e.data.id!==runId)return;clearTimeout(runTimer);busy=false;if(current!==window.pendingLesson){render();return;}const r=e.data;feedback=r.error?`<strong>JavaScript error:</strong> ${esc(r.error)}`:`<div><small>OUTPUT</small><pre>${esc(JSON.stringify(r.output)??'undefined')}</pre></div>${r.pass?`<strong class="positive">✓ Checks passed.</strong> ${lessons[current].explain}`:'The code ran, but the result did not pass the checks. Try again or open a hint.'}`;if(r.pass)complete();render()});
try{saved.note=localStorage.getItem('application-academy:note')||''}catch{}
const frame=document.createElement('iframe');frame.id='execution-frame';frame.src='sandbox.html';frame.sandbox='allow-scripts';frame.hidden=true;frame.title='Isolated exercise execution';document.body.append(frame);
addEventListener('hashchange',()=>{const n=Number(location.hash.slice(1));if(Number.isInteger(n)&&n>=0&&n<10&&n!==current)navigate(n)});
render();
